import{b as e,O as a,g as n,j as d}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"回归测试与上线标准","description":"","frontmatter":{},"headers":[],"relativePath":"testing/execution/regression-release/index.md","filePath":"测试理论与实践/2.测试执行过程/06.回归测试与上线标准.md","lastUpdated":1781688244000}'),r={name:"testing/execution/regression-release/index.md"};function s(l,t,o,i,h,g){return a(),n("div",null,[...t[0]||(t[0]=[d(`<h1 id="回归测试与上线标准" tabindex="-1">回归测试与上线标准 <a class="header-anchor" href="#回归测试与上线标准" aria-label="Permalink to &quot;回归测试与上线标准&quot;">​</a></h1><blockquote><p>新功能加上了，老功能还正常吗？上线前到底要检查哪些东西？这两件事做不好，就是在赌运气。</p></blockquote><h2 id="回归测试-确认-旧的东西没坏" tabindex="-1">回归测试：确认&quot;旧的东西没坏&quot; <a class="header-anchor" href="#回归测试-确认-旧的东西没坏" aria-label="Permalink to &quot;回归测试：确认&quot;旧的东西没坏&quot;&quot;">​</a></h2><p>回归测试的定义很简单——<strong>每次代码变更后，重新测试已有的功能，确保新改动没有破坏旧功能。</strong></p><p>听起来不复杂，但在快速迭代的项目里，回归测试往往是第一个被压缩的环节——&quot;这次就加了一个小按钮，不用回归了吧？&quot;然后那个按钮把整个表单提交逻辑搞挂了。</p><p>回归测试还有一个更深层的价值：<strong>没有可靠的回归套件，团队会害怕改代码。</strong> 重构变成赌博——&quot;改了这一行，谁知道哪里会炸&quot;。而有了稳定的自动化回归套件，团队就有底气频繁重构和优化。回归测试不只是&quot;找 bug&quot;，更是给整个团队提供一张<strong>安全网</strong>——网越密，团队越敢动代码。</p><h3 id="四种回归测试策略" tabindex="-1">四种回归测试策略 <a class="header-anchor" href="#四种回归测试策略" aria-label="Permalink to &quot;四种回归测试策略&quot;">​</a></h3><p>不是所有场景都需要把全部用例重跑一遍。按投入产出比选策略：</p><h4 id="策略一-完整回归" tabindex="-1">策略一：完整回归 <a class="header-anchor" href="#策略一-完整回归" aria-label="Permalink to &quot;策略一：完整回归&quot;">​</a></h4><p><strong>重新运行所有测试用例</strong>，不管这次改了什么。</p><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th><th>什么时候用</th></tr></thead><tbody><tr><td>覆盖最全面，不会漏</td><td>耗时长、成本高</td><td>核心架构变更、大版本发布前、金融/医疗等高风险系统</td></tr></tbody></table><blockquote><p>完整回归是最安全的，但也是最贵的。一个小改动就全量回归，等于用大炮打蚊子。</p></blockquote><h4 id="策略二-选择性回归" tabindex="-1">策略二：选择性回归 <a class="header-anchor" href="#策略二-选择性回归" aria-label="Permalink to &quot;策略二：选择性回归&quot;">​</a></h4><p><strong>只重新运行跟本次修改相关的测试用例。</strong></p><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th><th>什么时候用</th></tr></thead><tbody><tr><td>节省时间、聚焦风险</td><td>依赖对&quot;影响范围&quot;的准确判断——判断错了，该测的没测</td><td>大部分日常迭代场景</td></tr></tbody></table><p>选择什么用例？用<strong>影响分析</strong>来判断：</p><ul><li>改了哪个模块 → 跑这个模块的用例</li><li>改动的函数被哪些模块调用 → 这些模块的用例也要跑</li><li>修改涉及数据结构 → 所有读写这个数据的用例都要跑</li></ul><p>代码覆盖率工具（如 JaCoCo、Istanbul）可以帮你看出哪些代码被改动影响了。</p><h4 id="策略三-优先级回归" tabindex="-1">策略三：优先级回归 <a class="header-anchor" href="#策略三-优先级回归" aria-label="Permalink to &quot;策略三：优先级回归&quot;">​</a></h4><p><strong>只跑高优先级的测试用例。</strong></p><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th><th>什么时候用</th></tr></thead><tbody><tr><td>在有限时间内保证核心功能不受影响</td><td>低优先级用例积压不跑，风险会积累</td><td>时间紧、改动大的迭代</td></tr></tbody></table><p>优先级怎么定：</p><ul><li><strong>P0</strong>：核心业务流程（登录、下单、支付），每次必跑</li><li><strong>P1</strong>：重要但非核心功能，时间够就跑</li><li><strong>P2</strong>：边缘场景和低频功能，有时间再说</li></ul><h4 id="策略四-自动化回归" tabindex="-1">策略四：自动化回归 <a class="header-anchor" href="#策略四-自动化回归" aria-label="Permalink to &quot;策略四：自动化回归&quot;">​</a></h4><p><strong>用自动化测试工具跑回归用例。</strong></p><table tabindex="0"><thead><tr><th>优点</th><th>缺点</th><th>什么时候用</th></tr></thead><tbody><tr><td>效率高、可重复、CI/CD 友好</td><td>前期需要投入开发维护、不适合频繁变化的 UI</td><td>频繁迭代的项目、CI/CD 流程中</td></tr></tbody></table><p>自动化回归是四种策略里投入产出比最高的——一次投入持续受益。但前提是<strong>自动化测试本身是稳定的</strong>，否则&quot;用例挂了&quot;和&quot;环境问题&quot;分不清，反而浪费时间。</p><h3 id="四种策略怎么组合" tabindex="-1">四种策略怎么组合 <a class="header-anchor" href="#四种策略怎么组合" aria-label="Permalink to &quot;四种策略怎么组合&quot;">​</a></h3><p>实际项目中很少只用一种策略。常见组合：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每次代码提交：自动化回归（策略四）—— 跑 P0 级别的自动化用例</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>每日构建：优先级回归（策略三）—— 跑所有 P0 + P1 自动化用例</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>迭代结束：选择性回归（策略二）—— 针对本次改动的完整回归</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>大版本发布：完整回归（策略一）—— 全量用例 + 手工探索</span></span></code></pre></div><p>这种&quot;分层回归&quot;的思路和<a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>的部署管道一脉相承——越靠近提交，回归越轻量快速；越靠近发布，回归越全面。</p><p>给每层回归加一个<strong>时间预算</strong>硬约束，会让策略更落地：</p><table tabindex="0"><thead><tr><th>层级</th><th>时间上限</th><th>为什么</th></tr></thead><tbody><tr><td>提交阶段（自动化回归）</td><td>&lt; 5 分钟</td><td>超过 5 分钟，开发者会失去耐心、跳过等待、或者干脆不跑了</td></tr><tr><td>验收阶段（选择性/优先级回归）</td><td>&lt; 1 小时</td><td>超过 1 小时，就无法在一天内跑多轮反馈</td></tr><tr><td>发布前（完整回归）</td><td>按需，但要在发布窗口内完成</td><td>这是最后一道防线，时间服从质量</td></tr></tbody></table><p>时间预算不是&quot;跑到哪算哪&quot;，而是<strong>倒逼你精选用例</strong>——5 分钟内跑不完，不是放宽时间限制，而是砍用例、优化速度、或者拆分管道。</p><p>此外，自动化回归覆盖的是&quot;你知道要测什么&quot;，但新改动可能引入你完全没想到的问题——<strong>只有探索式测试能发现这些盲区。</strong> 在分层回归的每一层末尾，都值得补一轮简短的探索式测试（哪怕 15 分钟），用人的创造力弥补自动化脚本的机械性。<a href="/testing/methodology/exploratory-testing-1.html">探索式测试（上）</a>和<a href="/testing/methodology/exploratory-testing-2.html">探索式测试（下）</a>会详细展开。</p><h2 id="上线前检查清单" tabindex="-1">上线前检查清单 <a class="header-anchor" href="#上线前检查清单" aria-label="Permalink to &quot;上线前检查清单&quot;">​</a></h2><p>回归跑完了，Bug 修完了，是不是就可以上线了？上线不只是&quot;测试通过了&quot;——每一项都要确认到位才能点&quot;发布&quot;按钮（详见<a href="/testing/appendix/release-checklist.html">附录：产品上线</a>）：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>检查项</th><th>一句话</th><th style="text-align:center;">谁来确认</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>测试报告结论</strong></td><td>测试报告明确写了&quot;建议上线&quot;吗？</td><td style="text-align:center;">测试负责人</td></tr><tr><td style="text-align:center;">2</td><td><strong>遗留缺陷评估</strong></td><td>未修复的 Bug 有哪些？有没有规避方案？影响范围可控吗？</td><td style="text-align:center;">测试 + 产品</td></tr><tr><td style="text-align:center;">3</td><td><strong>回归测试通过</strong></td><td>最后一轮回归有没有新增问题？核心链路全绿吗？</td><td style="text-align:center;">测试</td></tr><tr><td style="text-align:center;">4</td><td><strong>性能基准达标</strong></td><td>关键接口的 P95/P99 是否满足上线标准？</td><td style="text-align:center;">测试/运维</td></tr><tr><td style="text-align:center;">5</td><td><strong>数据备份完成</strong></td><td>数据库、配置文件、旧版本包是否已备份？</td><td style="text-align:center;">DBA/运维</td></tr><tr><td style="text-align:center;">6</td><td><strong>回滚方案就绪</strong></td><td>出问题怎么回退？谁来操作？预计多久恢复？</td><td style="text-align:center;">运维 + 开发</td></tr><tr><td style="text-align:center;">7</td><td><strong>监控告警配置</strong></td><td>核心指标（错误率、响应时间、业务量）的告警阈值配好了吗？</td><td style="text-align:center;">运维</td></tr><tr><td style="text-align:center;">8</td><td><strong>值班人员确认</strong></td><td>上线后谁盯着？联系方式都通吗？</td><td style="text-align:center;">项目经理</td></tr><tr><td style="text-align:center;">9</td><td><strong>上线公告已发</strong></td><td>用户、运营、客服知道要上线/维护吗？</td><td style="text-align:center;">产品/项目经理</td></tr></tbody></table><blockquote><p>8 和 9 看起来和测试无关，但上线出了问题找不到人或客服被打爆——这些都是测试环节没闭环的表现。完整检查单和上线全流程见<a href="/testing/appendix/release-checklist.html">附录：产品上线</a>。</p></blockquote><h2 id="灰度发布-分阶段放量验证" tabindex="-1">灰度发布：分阶段放量验证 <a class="header-anchor" href="#灰度发布-分阶段放量验证" aria-label="Permalink to &quot;灰度发布：分阶段放量验证&quot;">​</a></h2><p>检查清单全部通过，不代表可以直接全量推给所有用户。业界标准的做法是<strong>分阶段放量</strong>（详见<a href="/testing/appendix/release-checklist.html">附录：产品上线</a>）：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:center;">放量比例</th><th style="text-align:center;">观察时间</th><th>做什么</th><th>通过标准</th></tr></thead><tbody><tr><td><strong>灰度发布</strong></td><td style="text-align:center;">1%~5%</td><td style="text-align:center;">≥ 30 分钟</td><td>推给少量真实用户，观察错误率、核心业务指标</td><td>无新增 5xx，核心链路成功率不变</td></tr><tr><td><strong>小流量放量</strong></td><td style="text-align:center;">10%~30%</td><td style="text-align:center;">≥ 1 小时</td><td>扩大用户范围，对比新旧版本的关键指标</td><td>性能无劣化，业务转化率无下降</td></tr><tr><td><strong>全量发布</strong></td><td style="text-align:center;">100%</td><td style="text-align:center;">—</td><td>全量推送，持续监控</td><td>错误率、响应时间平稳</td></tr></tbody></table><blockquote><p>每进入下一阶段前，必须确认上一阶段的监控数据正常。任何阶段出现问题，立即暂停发布、评估是否回滚。</p></blockquote><h3 id="常见的上线策略" tabindex="-1">常见的上线策略 <a class="header-anchor" href="#常见的上线策略" aria-label="Permalink to &quot;常见的上线策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适用场景</th><th style="text-align:center;">回滚难度</th></tr></thead><tbody><tr><td><strong>滚动发布</strong></td><td>逐个/逐批替换实例，新旧短暂共存</td><td>无状态服务、实例多</td><td style="text-align:center;">低</td></tr><tr><td><strong>蓝绿部署</strong></td><td>旧环境（蓝）和新环境（绿）并存，切换流量</td><td>需要快速回滚的场景</td><td style="text-align:center;">极低</td></tr><tr><td><strong>金丝雀发布</strong></td><td>先放一小部分流量到新版本，验证后再全量</td><td>高风险变更、核心链路</td><td style="text-align:center;">低</td></tr><tr><td><strong>功能开关</strong></td><td>代码部署到所有节点，通过开关控制功能可见性</td><td>需要按用户/区域逐步放开</td><td style="text-align:center;">极低</td></tr></tbody></table><blockquote><p>功能开关是实现最细粒度控制的策略——出问题关开关即可，不需要回滚代码。高风险功能优先考虑这种方式。</p></blockquote><h3 id="上线后验证与回滚" tabindex="-1">上线后验证与回滚 <a class="header-anchor" href="#上线后验证与回滚" aria-label="Permalink to &quot;上线后验证与回滚&quot;">​</a></h3><p>代码推上去不等于上线完成。附录中强调了三件事：</p><ol><li><strong>线上冒烟</strong>：在生产环境快速跑一遍核心用户流程，确认功能在真实环境中正常</li><li><strong>监控盯盘</strong>：上线后至少盯服务健康、响应时间、业务指标、资源、日志五大维度 30 分钟以上</li><li><strong>回滚标准前置</strong>：上线前就约定好什么情况 P0 立即回滚（核心链路不可用、大量 5xx、数据错乱），不要在出问题时才讨论&quot;要不要回&quot;</li></ol><h3 id="灰度发布和测试的关系" tabindex="-1">灰度发布和测试的关系 <a class="header-anchor" href="#灰度发布和测试的关系" aria-label="Permalink to &quot;灰度发布和测试的关系&quot;">​</a></h3><p>灰度不是测试的替代品，是测试的最后一道防线：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>功能测试 → 性能测试 → 安全测试 → 上线检查清单 → 灰度发布（灰度→小流量→全量）</span></span>
<span class="line"><span>(测试环境)                                 (生产环境, 小范围验证)</span></span></code></pre></div><p>测试环境能覆盖 80% 的问题，剩下 20%（环境差异、真实用户行为、数据规模效应）只有灰度阶段能暴露。完整的上线全流程——包括回滚决策、上线复盘——见<a href="/testing/appendix/release-checklist.html">附录：产品上线</a>。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>回归测试不只是找 bug，更是团队的<strong>安全网</strong>——有了稳定回归套件，才敢放心重构</li><li>四种回归策略：完整、选择性、优先级、自动化，实际项目中<strong>分层组合使用</strong>——提交轻量、发布全面</li><li>每层回归有时间预算：提交阶段 &lt; 5 分钟、验收阶段 &lt; 1 小时——时间限制倒逼精选用例，不是放宽标准</li><li>选择性回归的关键是<strong>准确的影响分析</strong>——判断改了什么、影响了什么、应该重测什么</li><li>上线前必须过 9 项检查清单：测试结论、遗留缺陷、回归结果、性能达标、数据备份、回滚方案、监控告警、值班确认、上线公告——每一项都要有人确认</li><li><strong>灰度发布（灰度→小流量→全量）</strong> 是用最小成本验证最大风险的策略——每阶段验证通过再放量，出问题随时暂停或回滚</li><li>自动化回归覆盖&quot;你知道的&quot;，探索式测试发现&quot;你不知道你不知道的&quot;——两者互补，不是二选一</li></ol>`,55)])])}const u=e(r,[["render",s]]);export{c as __pageData,u as default};
